custom_qss:
/* VIVID v2 — purple-dominant. Many gradients, soft rose used sparingly,
   overall brightness pulled well down. Zero borders: separation is done
   with large soft radii, layered fills and spacing alone. */

* {
    border: none;
    background-color: transparent !important;
    color: #ddd2ea !important;
}

QAbstractScrollArea, QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget {
    background: transparent !important;
    border: none;
}

/* window: deep violet with a plum lift at the floor */
QMainWindow {
    background: qlineargradient(x1:0, y1:0, x2:0.14, y2:1,
        stop:0 #1c1030, stop:0.4 #150c25, stop:0.75 #100919, stop:1 #180d26) !important;
}
QDialog {
    background: qlineargradient(x1:0, y1:0, x2:0.14, y2:1,
        stop:0 #1c1030, stop:0.5 #140b22, stop:1 #0f0817) !important;
}

QMenuBar { background: transparent !important; }
QMenuBar::item {
    padding: 5px 13px;
    border-radius: 7px;
    background: transparent !important;
    color: #907fa8 !important;
}
QMenuBar::item:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #3d2560, stop:1 #5a3580) !important;
    color: #eadff2 !important;
}
QMenuBar::item:disabled { color: #564a6b !important; }

QMenu {
    background: qlineargradient(x1:0, y1:0, x2:0.3, y2:1,
        stop:0 #241636, stop:1 #1a0f28) !important;
    border-radius: 12px;
    padding: 7px;
}
QMenu::item {
    padding: 7px 26px 7px 14px;
    border-radius: 8px;
    background: transparent !important;
    color: #ddd2ea !important;
}
QMenu::item:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #6d3fa8, stop:0.6 #8b5cd6, stop:1 #a97fe8) !important;
    color: #ffffff !important;
}
QMenu::item:disabled { color: #564a6b !important; }
QMenu::separator { height: 1px; background: #3a2852; margin: 6px 10px; }
QMenu::icon { padding-left: 6px; }

QToolBar { background: transparent !important; spacing: 3px; padding: 4px; }
QToolBar::separator { background: #3a2852; width: 2px; margin: 6px 5px; border-radius: 1px; }
QToolBar QToolButton {
    background: transparent !important;
    padding: 6px 10px;
    border-radius: 8px;
    color: #907fa8 !important;
}
QToolBar QToolButton:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #3a2560, stop:1 #2a1a44) !important;
    color: #eadff2 !important;
}
QToolBar QToolButton:checked, QToolBar QToolButton:pressed {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #7b4bc4, stop:1 #a97fe8) !important;
    color: #ffffff !important;
}
QToolBar QToolButton:disabled { color: #564a6b !important; }

QToolButton {
    background: transparent !important;
    padding: 6px 10px;
    border-radius: 8px;
    color: #907fa8 !important;
}
QToolButton:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #3a2560, stop:1 #2a1a44) !important;
    color: #eadff2 !important;
}
QToolButton:checked, QToolButton:pressed {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #7b4bc4, stop:1 #a97fe8) !important;
    color: #ffffff !important;
}
QToolButton:disabled { color: #564a6b !important; }

/* buttons: layered violet plating, soft sheen line inside the gradient */
QPushButton {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #3d2560, stop:0.35 #33204f, stop:1 #241640) !important;
    border-radius: 12px;
    padding: 8px 22px;
    color: #ddd2ea !important;
    font-weight: 600;
}
QPushButton:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #543070, stop:0.12 #6d3fa8, stop:0.55 #4a2a72,
        stop:1 #2e1c48) !important;
    color: #f6ecff !important;
}
QPushButton:pressed {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #241640, stop:0.5 #3d2560, stop:0.9 #6d3fa8, stop:1 #8b5cd6) !important;
    color: #ffffff !important;
}
QPushButton:checked {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #6d3fa8, stop:0.5 #8b5cd6, stop:1 #c08ce8) !important;
    color: #ffffff !important;
}
QPushButton:disabled {
    background: #1c1230 !important;
    color: #564a6b !important;
}
QPushButton::menu-indicator {
    subcontrol-origin: margin; width: 14px; height: 10px;
    background: transparent !important; border: none;
}

QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #241636, stop:1 #1c1130) !important;
    border-radius: 10px;
    padding: 6px 12px;
    color: #eadff2 !important;
    selection-background-color: #6d3fa8;
    selection-color: #ffffff;
}
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus, QTextEdit:focus, QPlainTextEdit:focus {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #32204e, stop:1 #281844) !important;
    color: #ffffff !important;
}
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled,
QTextEdit:disabled, QPlainTextEdit:disabled { color: #564a6b !important; }
QSpinBox::up-button, QSpinBox::down-button,
QDoubleSpinBox::up-button, QDoubleSpinBox::down-button {
    background: transparent !important; border: none; width: 16px;
}

QComboBox {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #3d2560, stop:1 #241640) !important;
    border-radius: 10px;
    padding: 6px 12px;
    color: #ddd2ea !important;
}
QComboBox:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #543070, stop:1 #33204f) !important;
}
QComboBox:focus {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #6d3fa8, stop:1 #4a2a72) !important;
}
QComboBox::drop-down { border: none; background: transparent !important; width: 18px; }
QComboBox QAbstractItemView {
    background: qlineargradient(x1:0, y1:0, x2:0.3, y2:1,
        stop:0 #241636, stop:1 #1a0f28) !important;
    border-radius: 12px;
    padding: 6px;
    selection-background-color: #6d3fa8;
    selection-color: #ffffff;
}
QComboBox:disabled { color: #564a6b !important; }

QCheckBox, QRadioButton {
    color: #ddd2ea !important;
    background: transparent !important;
    padding: 3px;
}
QCheckBox::indicator, QRadioButton::indicator {
    width: 20px; height: 20px;
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #32204e, stop:1 #221436) !important;
    border-radius: 6px;
}
QRadioButton::indicator { border-radius: 10px; }
QCheckBox::indicator:hover, QRadioButton::indicator:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #4a2a72, stop:1 #32204e) !important;
}
QCheckBox::indicator:checked, QRadioButton::indicator:checked {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #8b5cd6, stop:1 #6d3fa8) !important;
}
QCheckBox:disabled, QRadioButton:disabled { color: #564a6b !important; }

QTabBar { background: transparent !important; }
QTabBar::tab {
    background: transparent !important;
    color: #907fa8 !important;
    padding: 8px 20px;
    border-radius: 10px;
    margin: 0 3px;
}
QTabBar::tab:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #32204e, stop:1 #241636) !important;
    color: #ddd2ea !important;
}
QTabBar::tab:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #6d3fa8, stop:0.6 #8b5cd6, stop:1 #b98ae8) !important;
    color: #ffffff !important;
    font-weight: 600;
}
QTabBar::tab:disabled { color: #564a6b !important; }
QTabBar::close-button { background: transparent !important; border: none; border-radius: 4px; }
QTabBar::close-button:hover { background: #7b4bc4 !important; }
QTabWidget::pane { background: transparent !important; }

/* docks: gradient pill title */
QDockWidget { background: transparent !important; border: none; }
QDockWidget::title {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #32204e, stop:0.55 #3d2560, stop:1 #543070) !important;
    border-radius: 10px;
    padding: 7px 12px;
    margin: 3px;
    color: #e2d3ef !important;
    font-weight: 700;
}
QDockWidget::close-button, QDockWidget::float-button {
    background: transparent !important; border: none; padding: 3px; border-radius: 5px;
}
QDockWidget::close-button:hover, QDockWidget::float-button:hover {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #7b4bc4, stop:1 #a97fe8) !important;
}

QGroupBox {
    background: transparent !important;
    border: none;
    margin-top: 16px;
    padding-top: 6px;
    font-weight: 600;
    color: #ddd2ea !important;
}
QGroupBox::title {
    subcontrol-origin: margin;
    subcontrol-position: top left;
    padding: 0 8px;
    background: transparent !important;
    color: #b98ae8 !important;
}

QAbstractItemView {
    background: qlineargradient(x1:0, y1:0, x2:0.2, y2:1,
        stop:0 #20122f, stop:1 #1a0f28) !important;
    border-radius: 12px;
    alternate-background-color: #251539;
    selection-background-color: #6d3fa8;
    selection-color: #ffffff;
    outline: none;
}
QAbstractItemView::item { padding: 5px 8px; border-radius: 6px; }
QAbstractItemView::item:hover {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #32204e, stop:1 #281844) !important;
}
QAbstractItemView::item:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #6d3fa8, stop:1 #8b5cd6) !important;
    color: #ffffff !important;
}
QAbstractItemView::item:selected:!active {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #3a2560, stop:1 #4a2a72) !important;
}
QTreeView::item, QTreeWidget::item, QTreeWidgetItem,
QTableView::item, QListView::item, QListWidget::item {
    background: transparent !important;
}

QHeaderView { background: transparent !important; border: none; }
QHeaderView::section {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #3d2560, stop:1 #281844) !important;
    border-radius: 8px;
    padding: 7px 10px;
    margin: 2px;
    color: #d6c8e4 !important;
    font-weight: 600;
}
QHeaderView::section:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #543070, stop:1 #3d2560) !important;
}

/* scrollbars: violet handles with a soft rose tip when active */
QScrollBar:vertical { background: transparent !important; width: 14px; margin: 3px; }
QScrollBar::handle:vertical {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #4a2a72, stop:1 #6d3fa8) !important;
    border-radius: 7px;
    min-height: 30px;
}
QScrollBar::handle:vertical:hover {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #7b4bc4, stop:1 #b98ae8) !important;
}
QScrollBar::handle:vertical:pressed { background: #c08ce8 !important; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {
    height: 0; background: none; border: none;
}
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {
    background: transparent !important;
}
QScrollBar:horizontal { background: transparent !important; height: 14px; margin: 3px; }
QScrollBar::handle:horizontal {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #4a2a72, stop:1 #6d3fa8) !important;
    border-radius: 7px;
    min-width: 30px;
}
QScrollBar::handle:horizontal:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #7b4bc4, stop:1 #b98ae8) !important;
}
QScrollBar::handle:horizontal:pressed { background: #c08ce8 !important; }
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal {
    width: 0; background: none; border: none;
}
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal {
    background: transparent !important;
}
QScrollBar::corner { background: transparent !important; }

QSlider::groove:horizontal {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #2a1a44, stop:1 #1c1230) !important;
    height: 8px; border-radius: 4px;
}
QSlider::sub-page:horizontal {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #6d3fa8, stop:1 #a97fe8) !important;
    border-radius: 4px;
}
QSlider::add-page:horizontal {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #2a1a44, stop:1 #1c1230) !important;
    border-radius: 4px;
}
QSlider::handle:horizontal {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #f0e6f6, stop:1 #c9b3d8) !important;
    width: 20px; margin: -6px 0; border-radius: 10px;
}
QSlider::handle:horizontal:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #ffffff, stop:1 #e0c8ec) !important;
}
QSlider::groove:vertical {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #2a1a44, stop:1 #1c1230) !important;
    width: 8px; border-radius: 4px;
}
QSlider::sub-page:vertical {
    background: qlineargradient(x1:0, y1:1, x2:0, y2:0,
        stop:0 #6d3fa8, stop:1 #a97fe8) !important;
    border-radius: 4px;
}
QSlider::add-page:vertical {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #2a1a44, stop:1 #1c1230) !important;
    border-radius: 4px;
}
QSlider::handle:vertical {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #f0e6f6, stop:1 #c9b3d8) !important;
    height: 20px; margin: 0 -6px; border-radius: 10px;
}
QSlider::handle:vertical:hover {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #ffffff, stop:1 #e0c8ec) !important;
}

QProgressBar {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #2a1a44, stop:1 #1c1230) !important;
    border-radius: 8px;
    text-align: center;
    color: #ddd2ea !important;
    min-height: 18px;
}
QProgressBar::chunk {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #5b3487, stop:0.45 #8b5cd6, stop:1 #c08ce8) !important;
    border-radius: 8px;
}

QStatusBar {
    background: transparent !important;
    border: none;
    color: #907fa8 !important;
}
QStatusBar::item { background: transparent !important; }
QStatusBar QLabel { color: #907fa8 !important; }

QToolTip {
    background: qlineargradient(x1:0, y1:0, x2:0.2, y2:1,
        stop:0 #2a1a44, stop:1 #20122f) !important;
    border-radius: 8px;
    padding: 6px 10px;
    color: #eadff2 !important;
}

QSplitter { background: transparent !important; border: none; }
QSplitter::handle {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #3a2560, stop:1 #4a2a72) !important;
    border-radius: 3px; margin: 2px;
}
QSplitter::handle:hover { background: #7b4bc4 !important; }
